INSERT INTO `careers` VALUES (780,'product-manager','Product Manager','Technology','🧭','Brings technology, business and people together to create products that solve real problems.','Product Managers decide WHAT to build and WHY. They talk to users, spot problems, work with designers and engineers, and turn ideas into products people actually love.','Talk to users to find what they need. Prioritize features. Write clear specs. Coordinate engineers and designers. Measure whether a product is working and iterate.','[\"communication\", \"problem solving\", \"leadership\", \"analytical thinking\", \"creativity\", \"empathy\"]','[\"computer science\", \"business\", \"psychology\", \"economics\", \"mathematics\"]','[\"Computer Science\", \"Business / MBA\", \"Engineering\", \"Psychology\", \"Design\"]','[\"Technology\", \"Fintech\", \"E-commerce\", \"Healthcare\", \"SaaS\"]','[\"VP of Product\", \"Founder / CEO\", \"Product Director\", \"Startup Product Lead\"]','$120k - $180k (India: ₹25-60L)','Very strong — every company building software wants product leaders.','2026-09-18 20:59:51','TECH','[\"USA\", \"UK\", \"Australia\", \"India\"]'),(781,'ai-engineer','AI Engineer','Technology','🤖','Builds intelligent systems — chatbots, recommendation engines, self-driving tech.','AI Engineers turn machine learning research into systems people use every day. You train models, build the software around them, and make AI reliable, fast and safe.','Design and train ML models. Build APIs to serve them. Collect and clean data. Improve accuracy and latency. Deploy and monitor models in production.','[\"programming\", \"mathematics\", \"problem solving\", \"statistics\", \"machine learning\", \"data engineering\"]','[\"computer science\", \"mathematics\", \"statistics\", \"physics\"]','[\"Computer Science\", \"AI / ML\", \"Mathematics\", \"Data Science\"]','[\"Technology\", \"Autonomous vehicles\", \"Healthcare\", \"Finance\", \"Robotics\"]','[\"ML Engineer\", \"Research Scientist\", \"AI Architect\", \"Founder\"]','$140k - $220k (India: ₹30-70L)','Explosive growth — AI is now the default layer of every product.','2026-09-18 20:59:51','AI_DATA','[\"USA\", \"UK\", \"Australia\", \"India\"]'),(782,'software-engineer','Software Engineer','Technology','💻','Designs, builds and ships the apps, websites and systems the world runs on.','Software Engineers write the code behind apps, websites and platforms. You solve problems by building — debugging, designing systems and turning requirements into working software.','Write and review code. Design systems that scale. Debug issues. Automate workflows. Collaborate with product and design on features.','[\"programming\", \"problem solving\", \"logical thinking\", \"attention to detail\", \"collaboration\", \"system design\"]','[\"computer science\", \"mathematics\", \"physics\"]','[\"Computer Science\", \"Software Engineering\", \"Information Technology\"]','[\"Technology\", \"Banking\", \"Gaming\", \"Transport\", \"Every industry\"]','[\"Senior Engineer\", \"Tech Lead\", \"Engineering Manager\", \"Solutions Architect\"]','$100k - $170k (India: ₹20-50L)','Consistently high demand forever.','2026-09-18 20:59:51','TECH','[\"USA\", \"UK\", \"Australia\", \"India\"]'),(783,'cybersecurity-analyst','Cybersecurity Analyst','Technology','🛡️','Protects systems and people from hackers, breaches and digital threats.','Cybersecurity Analysts defend organizations against attacks. You monitor systems, investigate incidents, test defences and build the security that keeps data safe.','Monitor networks for threats. Investigate security incidents. Run penetration tests. Manage firewalls and detection tools. Educate teams on safe practices.','[\"attention to detail\", \"problem solving\", \"networking\", \"programming\", \"ethical hacking\", \"curiosity\"]','[\"computer science\", \"mathematics\"]','[\"Cybersecurity\", \"Computer Science\", \"Information Security\"]','[\"Technology\", \"Banking\", \"Government\", \"Healthcare\", \"Defence\"]','[\"Security Engineer\", \"Penetration Tester\", \"CISO\", \"Security Architect\"]','$100k - $160k (India: ₹15-40L)','Critical workforce shortage — strong and growing demand.','2026-09-18 20:59:51','CYBER','[\"USA\", \"UK\", \"Australia\", \"India\"]'),(784,'data-scientist','Data Scientist','Technology','📊','Turns data into answers — what will customers want, what should a company do next.','Data Scientists find stories hidden inside data. You clean it, explore it, build models to predict the future, and explain what it all means to decision-makers.','Analyze data to find insights. Build predictive models. Run experiments (A/B tests). Visualize findings. Communicate recommendations to business teams.','[\"statistics\", \"programming\", \"curiosity\", \"communication\", \"machine learning\", \"critical thinking\"]','[\"mathematics\", \"statistics\", \"computer science\", \"economics\"]','[\"Data Science\", \"Statistics\", \"Computer Science\", \"Economics / Mathematics\"]','[\"Technology\", \"E-commerce\", \"Finance\", \"Healthcare\", \"Marketing\"]','[\"Senior Data Scientist\", \"ML Engineer\", \"Data Science Manager\", \"Analytics Leader\"]','$120k - $190k (India: ₹20-55L)','Very strong — every organization is becoming data-driven.','2026-09-18 20:59:51','AI_DATA','[\"USA\", \"UK\", \"Australia\", \"India\"]'),(785,'game-developer','Game Developer','Media','🎮','Builds the worlds, mechanics and stories inside video games.','Game Developers bring games to life with code, art and design. You build gameplay systems, graphics engines and the interactive experiences millions of people play.','Implement gameplay mechanics. Work with designers and artists. Optimize for performance. Write shaders and physics systems. Test and polish the player experience.','[\"programming\", \"creativity\", \"problem solving\", \"game design\", \"mathematics\", \"collaboration\"]','[\"computer science\", \"mathematics\", \"art\", \"physics\"]','[\"Computer Science\", \"Game Development\", \"Digital Media\", \"Computer Graphics\"]','[\"Gaming\", \"Entertainment\", \"EdTech\", \"Simulation\"]','[\"Senior Game Engineer\", \"Technical Director\", \"Lead Designer\", \"Indie Game Founder\"]','$90k - $160k (India: ₹15-40L)','Strong — gaming is bigger than film and music combined.','2026-09-18 20:59:51','MEDIA','[\"USA\", \"UK\", \"India\", \"Australia\"]'),(786,'ux-designer','UX Designer','Design','🎨','Designs apps and websites that are easy and delightful — not just pretty.','UX Designers make products feel intuitive. You research how people think and behave, sketch interfaces, test designs and refine until a product feels effortless.','User research and interviews. Wireframes and prototypes. Usability testing. Design systems. Collaborating with engineers on the final experience.','[\"empathy\", \"creativity\", \"communication\", \"research\", \"prototyping\", \"attention to detail\"]','[\"art\", \"psychology\", \"computer science\", \"design\"]','[\"Design\", \"Psychology\", \"Human-Computer Interaction\", \"Fine Arts\"]','[\"Technology\", \"E-commerce\", \"Banking\", \"EdTech\", \"Healthcare\"]','[\"Senior UX Designer\", \"Product Design Lead\", \"Design Manager\", \"Design Director\"]','$100k - $160k (India: ₹18-45L)','Strong — great user experience is now a competitive advantage.','2026-09-18 20:59:51','CREATIVE','[\"USA\", \"UK\", \"Australia\", \"India\"]'),(787,'product-designer','Product Designer','Design','🛠️','Shapes both how a product looks AND how it works end-to-end.','Product Designers own the full design of a product — research, UI, interaction and brand. It\'s UX + visual design + a deep focus on the product being useful and loved.','Define the product experience. Design interfaces and interactions. Prototype and test. Maintain a design system. Partner closely with PMs and engineers.','[\"creativity\", \"empathy\", \"prototyping\", \"systems thinking\", \"communication\", \"visual design\"]','[\"design\", \"art\", \"psychology\", \"computer science\"]','[\"Product Design\", \"Interaction Design\", \"HCI\", \"Visual Communication\"]','[\"Technology\", \"Startups\", \"Consumer apps\", \"Fintech\", \"Gaming\"]','[\"Senior Product Designer\", \"Design Lead\", \"Head of Design\", \"Product Manager\"]','$110k - $170k (India: ₹20-50L)','Strong — products win on craft.','2026-09-18 20:59:51','CREATIVE','[\"USA\", \"UK\", \"Australia\", \"India\"]'),(788,'architect','Architect','Design','🏛️','Designs buildings and spaces that shape how people live, work and feel.','Architects design buildings — balancing beauty, function, safety, sustainability and cost. You create drawings, models and technical plans that become places people use daily.','Design building concepts. Create technical drawings and 3D models. Choose materials and layouts. Manage projects with engineers and clients. Ensure safety and code compliance.','[\"creativity\", \"spatial thinking\", \"mathematics\", \"attention to detail\", \"communication\", \"project management\"]','[\"mathematics\", \"physics\", \"art\", \"design\"]','[\"Architecture\", \"Civil Engineering\"]','[\"Construction\", \"Real Estate\", \"Urban Design\", \"Interior Design\"]','[\"Senior Architect\", \"Design Principal\", \"Urban Planner\", \"Own Architecture Firm\"]','$90k - $160k (India: ₹12-35L)','Steady — cities and infrastructure always need good designers.','2026-09-18 20:59:51','CREATIVE','[\"USA\", \"UK\", \"Australia\", \"India\"]'),(789,'entrepreneur','Entrepreneur / Founder','Entrepreneurship','🚀','Builds companies from an idea — owning the vision, risk and reward.','Entrepreneurs create companies. You identify a problem, build a solution, find customers and grow a business — wearing many hats and learning constantly.','Find customer problems. Validate ideas. Build an MVP. Raise money or bootstrap. Hire a team. Sell, market and iterate faster than anyone else can.','[\"risk-taking\", \"resilience\", \"communication\", \"sales\", \"creativity\", \"leadership\", \"problem solving\"]','[\"business\", \"economics\", \"computer science\", \"psychology\"]','[\"Business / MBA\", \"Computer Science\", \"Engineering\", \"Any degree + hustle\"]','[\"Startups\", \"Technology\", \"E-commerce\", \"Every industry\"]','[\"Scale a company\", \"Investor / Venture Capital\", \"Serial Founder\", \"Intrapreneur / Exec\"]','$0 to unlimited (equity-driven)','High risk, high reward — the skills transfer into everything.','2026-09-18 20:59:51','ENTREPRENEUR','[\"USA\", \"India\", \"UK\", \"Australia\"]'),(790,'business-analyst','Business Analyst','Business','📈','Translates business problems into solutions — the bridge between people and systems.','Business Analysts figure out how organizations can work better. You study processes, talk to stakeholders, analyze data and define exactly what should change.','Analyze business processes. Gather requirements from stakeholders. Model and document solutions. Help choose software and tools. Measure results after changes.','[\"analytical thinking\", \"communication\", \"problem solving\", \"data analysis\", \"documentation\", \"stakeholder management\"]','[\"business\", \"economics\", \"mathematics\", \"computer science\"]','[\"Business\", \"Economics\", \"Information Systems\", \"Commerce\"]','[\"Banking\", \"Consulting\", \"Technology\", \"Retail\", \"Government\"]','[\"Senior Business Analyst\", \"Product Manager\", \"Consultant\", \"Program Manager\"]','$90k - $140k (India: ₹12-30L)','Steady demand — organizations always need clearer decisions.','2026-09-18 20:59:51','BUSINESS','[\"USA\", \"UK\", \"Australia\", \"India\"]'),(791,'digital-marketer','Digital Marketer','Business','📣','Tells the world about products through content, ads, data and psychology.','Digital Marketers grow brands online. You craft campaigns, write copy, run ads, analyze what converts and make sure the right people find a product and love it.','Plan campaigns across social, search and email. Create content and copy. Run and optimize ad spend. Analyze data to improve performance. Build brand stories.','[\"creativity\", \"communication\", \"data analysis\", \"psychology\", \"copywriting\", \"curiosity\"]','[\"business\", \"psychology\", \"economics\", \"media\"]','[\"Business\", \"Marketing\", \"Media\", \"Psychology\"]','[\"E-commerce\", \"Technology\", \"Consumer brands\", \"Agencies\", \"Startups\"]','[\"Growth Marketer\", \"Brand Manager\", \"CMO\", \"Growth Consultant\"]','$80k - $150k (India: ₹10-35L)','Strong — every brand increasingly lives online.','2026-09-18 20:59:51','BUSINESS','[\"USA\", \"UK\", \"Australia\", \"India\"]'),(792,'doctor','Doctor (Physician)','Medicine','🩺','Diagnoses, treats and cares for patients — one of the most trusted roles in society.','Doctors protect health. You study the human body, diagnose illness, treat disease and help people live better — a long, demanding but deeply meaningful path.','Examine and diagnose patients. Prescribe treatment. Perform procedures. Monitor recovery. Communicate with patients and families. Keep learning for life.','[\"problem solving\", \"empathy\", \"communication\", \"resilience\", \"attention to detail\", \"science literacy\"]','[\"biology\", \"chemistry\", \"physics\", \"mathematics\"]','[\"MBBS\", \"MD\", \"Specialty Residency\"]','[\"Hospitals\", \"Clinics\", \"Research\", \"Public Health\"]','[\"Specialist (Cardiology, Surgery...)\", \"Surgeon\", \"Hospital Leader\", \"Medical Researcher\"]','$200k - $400k+ (India: ₹15-60L depending on specialty)','Always needed — one of the most durable careers.','2026-09-18 20:59:51','HEALTH','[\"USA\", \"Australia\", \"UK\", \"India\"]'),(793,'psychologist','Psychologist','Psychology','🧠','Understands how people think, feel and behave — and helps them thrive.','Psychologists study the mind and behavior. Some help individuals thrive through therapy; others work with organizations or run research that changes how we live.','Assess mental health and behavior. Provide therapy and support. Design interventions. Conduct research. Work with schools, companies and communities.','[\"empathy\", \"active listening\", \"communication\", \"critical thinking\", \"patience\", \"research\"]','[\"psychology\", \"biology\", \"mathematics\", \"statistics\"]','[\"Psychology\", \"Clinical Psychology\", \"Counselling\"]','[\"Healthcare\", \"Education\", \"HR / Organizations\", \"Research\", \"Tech (UX)\"]','[\"Clinical Psychologist\", \"Counsellor\", \"Organizational Psychologist\", \"Professor / Researcher\"]','$80k - $150k (India: ₹8-25L)','Growing strongly — mental health is now a global priority.','2026-09-18 20:59:51','HEALTH','[\"USA\", \"Australia\", \"UK\", \"India\"]'),(794,'financial-analyst','Financial Analyst','Finance','💹','Analyzes companies and markets to guide smart investment decisions.','Financial Analysts figure out what investments are worth. You study companies, build financial models, predict performance and recommend where money should go.','Build financial models. Analyze markets and companies. Prepare reports and valuations. Forecast budgets. Advise on investments and strategy.','[\"analytical thinking\", \"mathematics\", \"attention to detail\", \"financial modelling\", \"communication\"]','[\"mathematics\", \"economics\", \"accounting\", \"business\"]','[\"Finance\", \"Economics\", \"Accounting\", \"Business\"]','[\"Banking\", \"Investment\", \"Consulting\", \"Corporate Finance\", \"Asset Management\"]','[\"Senior Analyst\", \"Portfolio Manager\", \"Investment Banker\", \"CFO\"]','$100k - $200k (India: ₹15-40L)','Strong — every organization makes financial decisions.','2026-09-18 20:59:51','FINANCE','[\"USA\", \"UK\", \"Australia\", \"India\"]'),(795,'civil-engineer','Civil Engineer','Engineering','🏗️','Designs and builds bridges, roads, buildings and the infrastructure civilization runs on.','Civil Engineers build physical infrastructure. You design structures that are safe, sustainable and built to last — from skyscrapers to clean water systems.','Design structures and infrastructure. Run safety and feasibility analysis. Manage construction projects. Coordinate with architects and contractors. Ensure quality and compliance.','[\"mathematics\", \"physics\", \"problem solving\", \"project management\", \"attention to detail\"]','[\"mathematics\", \"physics\", \"chemistry\"]','[\"Civil Engineering\", \"Structural Engineering\"]','[\"Construction\", \"Infrastructure\", \"Real Estate\", \"Government\"]','[\"Senior Engineer\", \"Project Manager\", \"Structural Consultant\", \"Entrepreneur\"]','$90k - $160k (India: ₹10-30L)','Steady — infrastructure is a permanent need.','2026-09-18 20:59:51','ENGINEERING','[\"USA\", \"Australia\", \"UK\", \"India\"]'),(796,'robotics-engineer','Robotics Engineer','Engineering','🦾','Builds machines that move, sense and act — from factory arms to self-driving cars.','Robotics Engineers combine mechanical design, electronics and AI to build machines that can act in the physical world. It\'s where software meets hardware.','Design robot mechanisms and controls. Write software for sensing and autonomy. Build and test prototypes. Integrate electronics and motors. Optimize performance and safety.','[\"programming\", \"mathematics\", \"mechanics\", \"electronics\", \"problem solving\", \"physics\"]','[\"mathematics\", \"physics\", \"computer science\", \"electronics\"]','[\"Robotics\", \"Mechatronics\", \"Mechanical Engineering\", \"Computer Science\"]','[\"Manufacturing\", \"Automotive\", \"Healthcare robotics\", \"Aerospace\", \"Logistics\"]','[\"Senior Robotics Engineer\", \"Autonomy Lead\", \"Hardware Lead\", \"Founder\"]','$110k - $180k (India: ₹15-45L)','Strong and accelerating with automation.','2026-09-18 20:59:51','ENGINEERING','[\"USA\", \"Australia\", \"UK\", \"India\"]'),(797,'research-scientist','Research Scientist','Science','🔬','Explores the unknown and creates new knowledge that changes the world.','Research Scientists push the edge of what\'s known — in labs, in tech companies and in the field. You design experiments, analyze data and publish discoveries.','Design and run experiments. Analyze data and results. Read and write scientific papers. Collaborate across disciplines. Present findings to peers and the public.','[\"curiosity\", \"critical thinking\", \"mathematics\", \"experimentation\", \"writing\", \"resilience\"]','[\"biology\", \"chemistry\", \"physics\", \"mathematics\"]','[\"BSc / MSc / PhD in a science\"]','[\"Universities\", \"Tech (AI) research\", \"Pharma\", \"Government labs\", \"Biotech\"]','[\"Principal Investigator\", \"Head of Research\", \"Chief Scientist\", \"Professor\"]','$100k - $200k (India: ₹12-40L)','Steady in academia; booming in AI and biotech.','2026-09-18 20:59:51','SCIENCE','[\"USA\", \"UK\", \"Australia\", \"India\"]'),(798,'lawyer','Lawyer','Law','⚖️','Advocates for people and ideas — and shapes how society makes rules.','Lawyers interpret and use the law to protect, advise and represent people and organizations. You research, argue, negotiate and write with precision.','Research legal issues. Draft contracts and documents. Advise clients. Negotiate settlements. Represent clients in court and before regulators.','[\"critical thinking\", \"communication\", \"research\", \"persuasion\", \"attention to detail\", \"ethics\"]','[\"history\", \"political science\", \"english\", \"economics\"]','[\"Law (LLB / JD)\", \"Law + specializations\"]','[\"Law firms\", \"Courts\", \"Corporate\", \"Government\", \"NGOs\"]','[\"Corporate Lawyer\", \"Advocate\", \"Judge (later)\", \"Legal Counsel\", \"Policymaker\"]','$120k - $250k (India: ₹10-50L)','Steady — law grows with the complexity of the world.','2026-09-18 20:59:51','LAW','[\"USA\", \"UK\", \"Australia\", \"India\"]'),(799,'journalist','Journalist','Media','📰','Finds and tells the stories people need to know — simply and truthfully.','Journalists investigate, verify and report the news. You find stories, interview people, verify facts and share them through writing, video, audio or social media.','Pitch and research stories. Conduct interviews. Verify facts and sources. Write, edit or produce content. Publish across platforms and adapt to audiences.','[\"writing\", \"curiosity\", \"communication\", \"research\", \"critical thinking\", \"resilience\"]','[\"english\", \"history\", \"political science\", \"media\"]','[\"Journalism\", \"Media\", \"English\", \"Political Science\"]','[\"News\", \"Magazines\", \"Digital media\", \"Broadcast\", \"Podcasting\"]','[\"Senior Reporter\", \"Editor\", \"News Anchor\", \"Foreign Correspondent\", \"Media Founder\"]','$60k - $140k (India: ₹8-30L)','Evolving — great storytellers are still in demand.','2026-09-18 20:59:51','MEDIA','[\"USA\", \"UK\", \"India\", \"Australia\"]'),(800,'teacher','School Teacher / Educator','Education','🍎','Shapes the future by helping young people learn, think and grow.','Great teachers change lives. You plan lessons, explain ideas, inspire curiosity and guide students — in a classroom, online or through EdTech tools.','Plan and deliver lessons. Assess and support students. Adapt to different learners. Mentor and guide. Design learning experiences (often technology-enhanced).','[\"communication\", \"empathy\", \"patience\", \"creativity\", \"leadership\", \"public speaking\"]','[\"Your subject + education\"]','[\"Education\", \"Subject degree + teaching certification\"]','[\"Schools\", \"EdTech\", \"Tutoring\", \"Content\", \"Training\"]','[\"Lead Teacher\", \"Curriculum Designer\", \"EdTech Founder\", \"Principal\"]','$50k - $110k (India: ₹6-20L)','Stable — and expanding rapidly through EdTech.','2026-09-18 20:59:51','EDU','[\"USA\", \"UK\", \"Australia\", \"India\"]'),(801,'frontend-developer','Frontend Developer','Technology','💻','Frontend Developer — a career in technology that rewards programming and problem solving.','As a frontend developer, you focus on analytical thinking and learning agility to deliver real outcomes in the technology space. You learn by doing, adapt fast and build skills that compound over time.','You solve problems, work closely with people and teams, and improve every day. Day to day this involves attention to detail, collaboration and constant learning.','[\"programming\", \"problem solving\", \"analytical thinking\", \"learning agility\", \"attention to detail\", \"collaboration\"]','[\"computer science\", \"mathematics\", \"physics\"]','[\"Computer Science\", \"Software Engineering\", \"Information Technology\", \"Maths\"]','[\"Technology\", \"Fintech\", \"E-commerce\", \"Healthcare\", \"Startups\"]','[\"Senior Engineer\", \"Tech Lead\", \"Solutions Architect\", \"CTO\"]','$90k - $180k (India: ₹18-60L)','Very strong — technology talent stays in permanent demand.','2026-09-18 20:59:51','TECH','[\"USA\", \"UK\", \"Australia\", \"India\"]'),(802,'backend-developer','Backend Developer','Technology','💻','Backend Developer — a career in technology that rewards programming and problem solving.','As a backend developer, you focus on analytical thinking and learning agility to deliver real outcomes in the technology space. You learn by doing, adapt fast and build skills that compound over time.','You solve problems, work closely with people and teams, and improve every day. Day to day this involves attention to detail, collaboration and constant learning.','[\"programming\", \"problem solving\", \"analytical thinking\", \"learning agility\", \"attention to detail\", \"collaboration\"]','[\"computer science\", \"mathematics\", \"physics\"]','[\"Computer Science\", \"Software Engineering\", \"Information Technology\", \"Maths\"]','[\"Technology\", \"Fintech\", \"E-commerce\", \"Healthcare\", \"Startups\"]','[\"Senior Engineer\", \"Tech Lead\", \"Solutions Architect\", \"CTO\"]','$90k - $180k (India: ₹18-60L)','Very strong — technology talent stays in permanent demand.','2026-09-18 20:59:51','TECH','[\"USA\", \"UK\", \"Australia\", \"India\"]'),(803,'full-stack-developer','Full Stac